-- ════════════════════════════════════════════════════════════════════
-- VoltageAfrica CMS · 008 · Funders & press page, privacy policy, key facts
--   /press    key facts, downloads (validation report, logo pack, photos),
--             copy-ready descriptions, recognition
--   /privacy  privacy policy for the website's forms
--   homepage  "At a glance" key-facts strip directly after the hero
--
-- Safe to re-run: fixed IDs and "on conflict do nothing"; the homepage is only
-- reordered on the run that adds the key-facts strip.
-- ════════════════════════════════════════════════════════════════════
begin;

insert into public.pages (id, slug, title, seo_title, seo_description, status, is_system, sort_order) values
  ('2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'press', 'Funders & press', 'Funders & press', 'VoltageAfrica for funders, programme officers and journalists: key facts, research report, logos, photographs and ready-to-use descriptions.', 'published', true, 11),
  ('caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'privacy', 'Privacy policy', 'Privacy policy', 'How VoltageAfrica collects, uses and protects personal information submitted through this website.', 'published', true, 12)
on conflict do nothing;

insert into public.page_sections (id, page_id, type, label, content, settings, status, is_visible, sort_order)
select v.id::uuid, v.page_id::uuid, v.type, v.label, v.content::jsonb, v.settings::jsonb, 'published', true, v.sort_order
from (values
  ('4ddfbd7f-4fab-566c-8b08-6e3ca9ee9d2b', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'page_intro', null, '{"kicker":"Funders & press","headline":"Everything you need to *evaluate VoltageAfrica.*","intro":"Key facts, our research report, logos, photographs and ready-to-use descriptions, in one place. Figures link to their source or to our own research.","index":[{"label":"At a glance","anchor":"facts"},{"label":"Documents, logos & photographs","anchor":"downloads"},{"label":"About VoltageAfrica, ready to use","anchor":"about-texts"},{"label":"Recognition","anchor":"recognition"}]}', '{}', 0),
  ('b6b50171-ad8a-5656-9ee0-f9cc26627c4a', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'key_facts', null, '{"kicker":"At a glance","headline":"Where VoltageAfrica *stands today.*","items":[{"label":"First pilot hub","value":"In preparation","detail":"Shurugwi, Midlands Province, Zimbabwe. Not yet operational.","href":"/pilot"},{"label":"Community research","value":"5 villages","detail":"23 household interviews, 6 community leaders and 27 surveys (May 2025).","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf"},{"label":"Prototype","value":"Built & tested","detail":"Sun-tracking rig: four 15 W modules steered by a light sensor (2025).","href":"/technology#approach"},{"label":"Team","value":"4 people","detail":"Working across Zimbabwe, Rwanda and Kenya.","href":"/about"},{"label":"Recognition","value":"5 awards","detail":"Prizes and selections, including 2nd place at the BRICS+ Youth Innovation Summit 2026.","href":"/impact#awards"},{"label":"Building since","value":"2024","detail":"From an energy-trading prototype to field research and hardware.","href":"/journey"}],"note":"Status as of November 2026. The pilot hub is in preparation; VoltageAfrica does not yet operate a microgrid."}', '{"anchor":"facts","background":"paper"}', 1),
  ('d7f34d5b-4536-5658-8a06-aeec9deb3d41', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'downloads', null, '{"kicker":"Downloads","headline":"Documents, logos *and photographs.*","intro":"Download what you need. Documents marked “on request” are shared directly by email, so we can send the current version.","items":[{"group":"Documents","title":"Shurugwi community outreach & validation report","description":"Five villages, 23 household interviews, 6 community leaders and 27 surveys. May 2025.","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf","meta":"PDF · 3 pages · 216 KB"},{"group":"Documents","title":"Pitch deck","description":"Our presentation for investors, funders and partners.","href":"","meta":""},{"group":"Documents","title":"Venture overview & impact report","description":"The venture in detail: approach, technology and intended impact.","href":"","meta":""},{"group":"Documents","title":"Venture description","description":"A short written summary of VoltageAfrica.","href":"","meta":""},{"group":"Brand","title":"Logo pack","description":"Horizontal, stacked, symbol and wordmark logos in every tone, with usage guidance.","href":"/brand/voltageafrica-logo-pack.zip","meta":"ZIP · SVG + PNG · 1.6 MB"},{"group":"Brand","title":"Primary logo","description":"Horizontal logo for light backgrounds.","href":"/brand/logo-horizontal-primary.svg","meta":"SVG · 19 KB"},{"group":"Photographs","title":"Sean Mavhima, founder","description":"In the field, Zimbabwe.","href":"/images/founder/sean-field.jpg","meta":"JPG · 2200 × 1467 · 688 KB"},{"group":"Photographs","title":"Sun-tracking prototype, 2025","description":"Four 15 W modules steered by a central light sensor.","href":"/images/prototype/tracker-array.jpg","meta":"JPG · 1916 × 2000 · 574 KB"},{"group":"Photographs","title":"Climate education session, Kigali","description":"Students and the VoltageAfrica team after a renewable energy lesson.","href":"/images/outreach/kigali-school-group.jpg","meta":"JPG · 2000 × 1125 · 391 KB"}],"requestSubject":"Document request","note":"Photographs: © VoltageAfrica. You may use them in coverage of VoltageAfrica with the credit “VoltageAfrica”; for any other use, please ask. Please follow the logo guidance in the pack."}', '{"anchor":"downloads"}', 2),
  ('d8717e15-565a-5695-a226-f0e12ec8a16e', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'boilerplate', null, '{"kicker":"Ready to use","headline":"About VoltageAfrica, *in your word count.*","intro":"Copy any of these into an article, a programme application or an introduction. Each one is accurate as of November 2026.","blocks":[{"label":"One line","text":"VoltageAfrica designs intelligent solar microgrids for rural communities beyond the reach of the national grid, starting with a pilot hub in Shurugwi, Zimbabwe."},{"label":"About · short","text":"VoltageAfrica is building intelligent renewable energy infrastructure for rural Africa: community solar microgrids that combine generation, battery storage, smart metering and distribution, designed around the homes, schools and enterprises they serve. Founded by Sean Mavhima, the team works across Zimbabwe, Rwanda and Kenya. Its first pilot hub, in Shurugwi, Zimbabwe, is in preparation."},{"label":"About · long","text":"VoltageAfrica is building intelligent renewable energy infrastructure for communities the national grid has not reached. In rural Zimbabwe, only 23.4% of residents have grid electricity (ZimStat, 2022 census).\n\nEach VoltageAfrica hub is a complete local energy system: solar generation, battery storage, smart metering and a low-voltage network, sized around productive uses such as milling, irrigation and cold storage as well as homes, because income is what makes energy access last.\n\nThe venture began with research: in May 2025 the team engaged five villages in Shurugwi, held 23 household interviews and 6 interviews with community leaders, and collected 27 surveys. It has built and tested a sun-tracking prototype, and its first pilot hub in Shurugwi is in preparation. VoltageAfrica placed second in Sustainable Development and Green Solutions at the BRICS+ Youth Innovation Summit 2026 and was a finalist in the Global HackAtom International Student Championship."},{"label":"Founder bio","text":"Sean Mavhima is the founder and CEO of VoltageAfrica. He grew up in rural Zimbabwe, where access to electricity, textbooks and digital tools was a daily struggle. A Mastercard Foundation Scholar at the University of Rwanda, he works where energy, intelligent systems and entrepreneurship meet, building the infrastructure he grew up without for the communities that still live without it."}],"contactTitle":"Press & funder contact","contactNote":"We usually reply within a few working days."}', '{"anchor":"about-texts","background":"paper"}', 3),
  ('c577d8e1-6ac6-5fac-9439-e1f794152987', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'awards', null, '{"kicker":"Recognition","headline":"Prizes, selections *and fellowships.*","intro":"Each linked to its source where one exists."}', '{"anchor":"recognition","background":"parchment"}', 4),
  ('ed2026ca-c11a-5937-a933-7af508a2b834', 'caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'page_intro', null, '{"kicker":"Privacy policy","headline":"Your information, *handled with care.*","intro":"What we collect through this website, why, who can see it, and the choices you have. Last updated 20 November 2026.","index":[]}', '{}', 0),
  ('7a312210-ad6b-54ec-b45a-c17f8ca06469', 'caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'rich_text', null, '{"kicker":"","headline":"","body":"<h2>Who we are</h2><p>This website is run by VoltageAfrica (“we”, “us”), a venture building renewable energy infrastructure, working across Zimbabwe, Rwanda and Kenya. For any question about your personal information, use our <a href=\"/contact\">contact page</a> or email the address shown there.</p><h2>What we collect</h2><p>We only collect what you choose to send us through the forms on this site:</p><ul><li><strong>Partnership inquiries:</strong> your name, organisation, email, country, partnership category, proposal and message, and optionally your phone number and website or LinkedIn address.</li><li><strong>Support inquiries:</strong> your name, email, country, the kind of support you are offering, an optional amount and currency, and your message. Submitting this form is not a payment, and we never ask for card or bank details on this site.</li><li><strong>Contact messages:</strong> your name, email, subject, inquiry category and message.</li></ul><p>To protect the forms from spam and abuse, we also store a one-way hash of the network address each submission came from, never the address itself. Our hosting provider keeps short-lived technical logs (for example the pages requested and the browser used) to run the site securely.</p><h2>Cookies and similar technologies</h2><p>We do not use advertising or analytics cookies, and we do not track you across other websites. Your browser remembers two small preferences for the length of your visit: whether you chose the film or the 3D view on the homepage, and whether you have already seen its opening animation. Administrators who sign in to manage the site receive a sign-in cookie; visitors do not.</p><h2>How we use your information</h2><ul><li>to read and reply to your inquiry, and to follow up on a partnership, support offer or request you have made;</li><li>to keep records of those conversations;</li><li>to protect the site and its forms from abuse.</li></ul><p>We rely on your consent, which you give by ticking the consent box or by sending us a message, and on our legitimate interest in running and protecting the site. We do not sell your information, use it for automated decision-making or add you to a mailing list without asking.</p><h2>Who can see it</h2><p>Only VoltageAfrica’s administrators can see submissions. We use trusted service providers to operate the site: <strong>Supabase</strong> (secure database), <strong>Vercel</strong> (website hosting) and <strong>Resend</strong> (sending us a notification email when a submission arrives). They process data on our behalf and may store it on servers outside your country, under their own security and data-protection commitments. We share information with others only when the law requires it.</p><h2>How long we keep it</h2><p>We keep inquiries for as long as we need them to respond and to manage any relationship that follows. We review stored inquiries at least once a year and delete those we no longer need. You can ask us to delete yours at any time.</p><h2>Your rights</h2><p>You can ask to see the information we hold about you, to correct it, to delete it, or to withdraw your consent, and you can object to how we use it. Contact us and we will respond as quickly as we can, and within the time the law allows. You also have the right to complain to a data protection authority: in Zimbabwe, the Postal and Telecommunications Regulatory Authority (POTRAZ); in Rwanda, the National Cyber Security Authority; in Kenya, the Office of the Data Protection Commissioner; or the authority where you live.</p><h2>Security</h2><p>Submissions travel over an encrypted connection and are stored in a database that only signed-in administrators can read. No method of transmission or storage is completely secure, but we take reasonable steps to protect your information.</p><h2>Children</h2><p>Our forms are intended for adults. If you believe a child has sent us personal information, please contact us and we will delete it.</p><h2>Other websites</h2><p>This site links to other websites, such as news articles and photograph sources. Their privacy practices are their own.</p><h2>Changes to this policy</h2><p>We will update this page if the way we handle information changes. Last updated: 20 November 2026.</p>"}', '{"background":"paper"}', 1)
) as v(id, page_id, type, label, content, settings, sort_order)
where exists (select 1 from public.pages p where p.id = v.page_id::uuid)
on conflict (id) do nothing;

-- Homepage: make room after the hero, then add the key-facts strip (first run only)
update public.page_sections set sort_order = sort_order + 1
  where page_id = '9e36afb6-9da0-5bf9-91f6-c860dbce5e93' and sort_order >= 1
    and not exists (select 1 from public.page_sections where id = '4be3883c-fcfb-5b07-869d-f52fae7ace73');
insert into public.page_sections (id, page_id, type, label, content, settings, status, is_visible, sort_order)
select '4be3883c-fcfb-5b07-869d-f52fae7ace73'::uuid, '9e36afb6-9da0-5bf9-91f6-c860dbce5e93'::uuid, 'key_facts', 'At a glance', '{"kicker":"At a glance","headline":"","items":[{"label":"First pilot hub","value":"In preparation","detail":"Shurugwi, Midlands Province, Zimbabwe. Not yet operational.","href":"/pilot"},{"label":"Community research","value":"5 villages","detail":"23 household interviews, 6 community leaders and 27 surveys (May 2025).","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf"},{"label":"Prototype","value":"Built & tested","detail":"Sun-tracking rig: four 15 W modules steered by a light sensor (2025).","href":"/technology#approach"},{"label":"Team","value":"4 people","detail":"Working across Zimbabwe, Rwanda and Kenya.","href":"/about"},{"label":"Recognition","value":"5 awards","detail":"Prizes and selections, including 2nd place at the BRICS+ Youth Innovation Summit 2026.","href":"/impact#awards"},{"label":"Building since","value":"2024","detail":"From an energy-trading prototype to field research and hardware.","href":"/journey"}],"note":""}'::jsonb, '{"anchor":"at-a-glance"}'::jsonb, 'published', true, 1
where exists (select 1 from public.pages where id = '9e36afb6-9da0-5bf9-91f6-c860dbce5e93')
on conflict (id) do nothing;

